def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    if horizon <= 0:
        return []
    y = []
    for v in history:
        try:
            x = float(v)
            y.append(x if math.isfinite(x) else 0.0)
        except Exception:
            y.append(0.0)
    if not y:
        return [0.0] * horizon

    def fit_predict(train, steps, w, p):
        a = train[-min(w, len(train)):]
        z = [max(0.0, v) ** p for v in a]
        m = len(z)
        if m < 2:
            return [max(0.0, a[-1])] * steps
        xm = (m - 1) / 2.0
        zm = sum(z) / m
        den = sum((i - xm) ** 2 for i in range(m))
        slope = sum((i - xm) * (z[i] - zm) for i in range(m)) / den if den else 0.0
        intercept = zm - slope * xm
        out = []
        for k in range(1, steps + 1):
            q = max(0.0, intercept + slope * (m - 1 + k))
            value = q ** (1.0 / p)
            out.append(value if math.isfinite(value) else 0.0)
        return out

    n = len(y)
    candidates = []
    for p in (0.35, 0.5, 0.65, 1.0):
        for w in (16, 24, 32, 48, 64):
            if w <= n:
                errors = []
                block = min(12, max(4, horizon // 4))
                for back in (block, 2 * block, 3 * block):
                    cut = n - back
                    if cut < w or cut + block > n:
                        continue
                    pred = fit_predict(y[:cut], block, w, p)
                    for j, f in enumerate(pred):
                        actual = y[cut + j]
                        errors.append(2.0 * abs(f - actual) / (abs(f) + abs(actual) + 1e-9))
                if errors:
                    candidates.append((sum(errors) / len(errors), p, w))
    if not candidates:
        return [max(0.0, y[-1])] * horizon
    _, p, w = min(candidates)
    return fit_predict(y, horizon, w, p)

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    if horizon <= 0:
        return []
    y = []
    for v in history:
        try:
            x = float(v)
            y.append(max(0.0, x) if math.isfinite(x) else 0.0)
        except Exception:
            y.append(0.0)
    if not y:
        return [0.0] * horizon
    w = min(48, len(y))
    z = [math.sqrt(v) for v in y[-w:]]
    if len(z) < 2:
        return [y[-1]] * horizon
    slopes = []
    for lag in (1, 2, 3, 4, 6, 8):
        if lag < len(z):
            for i in range(len(z) - lag, max(lag - 1, len(z) - 20 - lag), -1):
                slopes.append((z[i] - z[i - lag]) / lag)
    slope = statistics.median(slopes) if slopes else 0.0
    recent_diffs = [z[i] - z[i - 1] for i in range(max(1, len(z) - 12), len(z))]
    local = statistics.median(recent_diffs) if recent_diffs else slope
    slope = 0.65 * local + 0.35 * slope
    if slope > 0.0 and z[-1] < z[0]:
        slope = 0.0
    out = []
    for k in range(1, horizon + 1):
        q = max(0.0, z[-1] + slope * k)
        value = q * q
        out.append(value if math.isfinite(value) else 0.0)
    return out
